        } catch (Exception e) {
            throw new SearchException('Query execution failed: ' + e.getMessage());
        }
    }

    // ---------- private helpers ----------

    private static String resolveObjectName(String apiName) {
        Map<String, Schema.SObjectType> globalMap = Schema.getGlobalDescribe();
        String lower = apiName.toLowerCase();
        for (String key : globalMap.keySet()) {
            if (key.toLowerCase() == lower) {
                return key;
            }
        }
        return null;
    }

    private static Boolean isFilterable(DescribeFieldResult df) {
        if (df == null) {
            return false;
        }
        String typeName = df.getType().name();
        return typeName != 'MultiselectPicklist' && typeName != 'Location';
