```apex
public class OrderPayloadParser {

    public class PayloadException extends Exception {}

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public static Order parse(String body) {
        if (body == null || body.trim().length() == 0) {
            throw new PayloadException('Request body is null or blank.');
        }

        Object rootObj;
        try {
            rootObj = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('Request body is not valid JSON.');
        }

        if (!(rootObj instanceof Map<String, Object>)) {
            throw new PayloadException('Request body must be a JSON object.');
        }

        Map<String, Object> data = (Map<String, Object>) rootObj;

        // number (required, non-blank string)
        if (!data.containsKey('number') || data.get('number') == null) {
            throw new PayloadException('Missing required field "number".');
        }
        if (!(data.get('number') instanceof String) || ((String) data.get('number')).trim().length() == 0) {
            throw new PayloadException('"number" must be a non-blank string.');
        }

        Order ord = new Order();
        ord.orderNumber = (String) data.get('number');

        // date (optional)
        if (data.containsKey('date') && data.get('date') != null && data.get('date') instanceof String) {
            try {
                ord.orderDate = Date.valueOf((String) data.get('date'));
            } catch (Exception e) {
                ord.orderDate = null;
            }
        }

        // currency (optional)
        if (data.containsKey('currency') && data.get('currency') != null && data.get('currency') instanceof String) {
            ord.currencyCode = (String) data.get('currency');
        }

        // customer (optional)
        if (data.containsKey('customer') && data.get('customer') != null
                && data.get('customer') instanceof Map<String, Object>) {
            Map<String, Object> custData = (Map<String, Object>) data.get('customer');
            if (custData.containsKey('email') && custData.get('email') != null
                    && custData.get('email') instanceof String) {
                ord.customerEmail = (String) custData.get('email');
            }
        }

        // lines
        ord.lines = new List<Line>();
        Decimal totalVal = 0;

        if (data.containsKey('lines') && data.get('lines') != null
                && data.get('lines') instanceof List<Object>) {
            List<Object> linesArr = (List<Object>) data.get('lines');
            for (Integer i = 0; i < linesArr.size(); i++) {
                if (!(linesArr[i] instanceof Map<String, Object>)) {
                    throw new PayloadException('Line at index ' + i + ' is not a JSON object.');
                }
                Map<String, Object> lnData = (Map<String, Object>) linesArr[i];

                // sku (required)
                if (!lnData.containsKey('sku') || lnData.get('sku') == null
                        || !(lnData.get('sku') instanceof String)
                        || ((String) lnData.get('sku')).trim().length() == 0) {
                    throw new PayloadException('Missing or invalid "sku" in line ' + i + '.');
                }

                // quantity (required, must be positive)
                if (!lnData.containsKey('quantity') || lnData.get('quantity') == null) {
                    throw new PayloadException('Missing "quantity" in line ' + i + '.');
                }
                Integer qty;
                if (lnData.get('quantity') instanceof Integer) {
                    qty = (Integer) lnData.get('quantity');
                } else if (lnData.get('quantity') instanceof Double) {
                    qty = (Integer) (Double) lnData.get('quantity');
                } else {
                    throw new PayloadException('Invalid "quantity" type in line ' + i + '.');
                }
                if (qty <= 0) {
                    throw new PayloadException('"quantity" must be positive in line ' + i + '.');
                }

                // unitPrice (required, must be non-negative)
                if (!lnData.containsKey('unitPrice') || lnData.get('unitPrice') == null) {
                    throw new PayloadException('Missing "unitPrice" in line ' + i + '.');
                }
                Decimal price;
                if (lnData.get('unitPrice') instanceof Integer) {
                    price = (Decimal) (Integer) lnData.get('unitPrice');
                } else if (lnData.get('unitPrice') instanceof Double) {
                    price = (Decimal) (Double) lnData.get('unitPrice');
                } else {
                    throw new PayloadException('Invalid "unitPrice" type in line ' + i + '.');
                }
                if (price < 0) {
                    throw new PayloadException('"unitPrice" must be non-negative in line ' + i + '.');
                }

                // discount (optional, defaults to 0)
                Decimal disc = 0;
                if (lnData.containsKey('discount') && lnData.get('discount') != null) {
                    if (lnData.get('discount') instanceof Integer) {
                        disc = (Decimal) (Integer) lnData.get('discount');
                    } else if (lnData.get('discount') instanceof Double) {
                        disc = (Decimal) (Double) lnData.get('discount');
                    }
                }

                // lineTotal = quantity * unitPrice * (1 - discount), rounded half-up to 2 dp
                Decimal raw = (Decimal) qty * price * ((Decimal) 1 - disc);
                Decimal lineTotal = (Decimal) System.Math.round(raw.doubleValue() * 100) / 100;

                Line ln = new Line();
                ln.sku = (String) lnData.get('sku');
                ln.quantity = qty;
                ln.unitPrice = price;
                ln.discount = disc;
                ln.lineTotal = lineTotal;

                ord.lines.add(ln);
                totalVal += lineTotal;
            }
        }

        ord.total = totalVal;
        return ord;
    }

    public static String toAcknowledgement(Order ord) {
        JSONGenerator gen = JSON.createGenerator(false);
        gen.writeStartObject();
        gen.writeStringField('number', ord.orderNumber);
        gen.writeStringField('status', 'RECEIVED');
        gen.writeNumberField('lineCount', ord.lines == null ? 0 : ord.lines.size());
        gen.writeNumberField('total', ord.total == null ? (Decimal) 0 : ord.total);
        gen.writeEndObject();
        return gen.getAsString();
    }
}
