public class PicklistService {

    public class Option {
        public String value { get; set; }
        public String label { get; set; }
        public Boolean isDefault { get; set; }

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }
    }

    public class PicklistServiceException extends Exception {}

    public static List<Option> activeOptions(String objectApiName, String fieldApiName) {
        if (String.isBlank(objectApiName) || String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Object and field API names must not be null or blank.');
        }

        // Resolve object (case-insensitive)
        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
        Schema.SObjectType objectType = null;
        for (String key : globalDescribe.keySet()) {
            if (key.equalsIgnoreCase(objectApiName)) {
                objectType = globalDescribe.get(key);
                break;
            }
        }

        if (objectType == null) {
            throw new PicklistServiceException('Object does not exist: ' + objectApiName);
        }

        // Resolve field (case-insensitive)
        Map<String, Schema.SObjectField> fields = objectType.getDescribe().fields.getMap();
        Schema.SObjectField objectField = null;
        for (String key : fields.keySet()) {
            if (key.equalsIgnoreCase(fieldApiName)) {
                objectField = fields.get(key);
                break;
            }
        }

        if (objectField == null) {
            throw new PicklistServiceException('Field does not exist on object ' + objectApiName + ': ' + fieldApiName);
        }

        // Get field describe and validate type
        Schema.DescribeFieldResult fieldDescribe = objectField.getDescribe();
        Schema.DisplayType fieldType = fieldDescribe.getType();

        if (fieldType != Schema.DisplayType.PICKLIST && fieldType != Schema.DisplayType.MULTISELECTPICKLIST) {
            throw new PicklistServiceException(
                'Field ' + fieldApiName + ' on ' + objectApiName + ' is not a picklist or multi-select picklist.'
            );
        }

        // Determine the default value
        Object rawDefault = fieldDescribe.getDefaultValue();
        String defaultValue = null;
        if (rawDefault != null) {
            if (rawDefault instanceof Schema.PicklistEntry) {
                defaultValue = ((Schema.PicklistEntry) rawDefault).getValue();
            } else {
                defaultValue = String.valueOf(rawDefault);
            }
        }

        // Build result: active values in defined order
        List<Schema.PicklistEntry> entries = fieldDescribe.getPicklistValues();
        List<Option> result = new List<Option>();

        if (entries != null) {
            for (Schema.PicklistEntry entry : entries) {
                if (entry.isActive()) {
                    Boolean isDefault = (defaultValue != null && entry.getValue() == defaultValue);
                    result.add(new Option(entry.getValue(), entry.getLabel(), isDefault));
                }
            }
        }

        return result;
    }
}
