public class LogPurgeJob implements Schedulable {

    public LogPurgeJob() {}

    public void execute(SchedulableContext sc) {
        Date thirtyDaysAgo = Date.today() - 30;
        Date oneEightyDaysAgo = Date.today() - 180;

        List<Id> idsToDelete = new List<Id>();

        // Non-ERROR (including blank) logs older than 30 days
        for (FB_Integration_Log__c log : [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE CreatedDate < :thirtyDaysAgo
              AND (Level__c != 'ERROR' OR Level__c = null)
        ]) {
            idsToDelete.add(log.Id);
        }

        // ERROR logs older than 180 days
        for (FB_Integration_Log__c log : [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE CreatedDate < :oneEightyDaysAgo
              AND Level__c = 'ERROR'
        ]) {
            idsToDelete.add(log.Id);
        }

        // Delete in chunks of 5 000 to stay within the per-DML governor limit
        List<Id> chunk = new List<Id>();
        for (Id id : idsToDelete) {
            chunk.add(id);
            if (chunk.size() == 5000) {
                Delete chunk;
                chunk.clear();
            }
        }
        if (!chunk.isEmpty()) {
            Delete chunk;
        }
    }

    public static Id scheduleNightly() {
        // 0 0 2 * * ?  →  every day at 02:00
        String cronExpression = '0 0 2 * * ?';
        return System.schedule('Log purge (nightly)', cronExpression, new LogPurgeJob());
    }
}
