@isTest
private class InvoicingServiceTest {

    // ---------- Tracking UoW (implements the interface so it can be injected via setMock) ----------
    private class TrackingUoW implements fflib_ISObjectUnitOfWork {
        public List<SObject> registered = new List<SObject>();
        public Integer commitCount = 0;

        public void registerDirty(SObject sObj) {
            registered.add(sObj);
        }
        public void registerDirty(SObject sObj, SObjectField field) {
            registered.add(sObj);
        }
        public void registerDirty(SObject sObj, SObjectField[] fields) {
            registered.add(sObj);
        }
        public void commitWork() {
            commitCount++;
        }
    }

    // ---------- Fake gateways (ApexMocks cannot .then().throw() for void methods) ----------
    private class AuthFailingGateway implements IBillingGateway {
        public void authenticate() {
            throw new BillingException('Connection refused');
        }
        public String createInvoice(Id accountId, Decimal amount) {
            throw new Exception('createInvoice must not be called after auth failure');
        }
    }

    private class SelectiveFailureGateway implements IBillingGateway {
        private Id failAccountId;
        private String failMessage;
        private String successPrefix;

        public SelectiveFailureGateway(Id failAccountId, String failMessage, String successPrefix) {
            this.failAccountId = failAccountId;
            this.failMessage = failMessage;
            this.successPrefix = successPrefix;
        }
        public void authenticate() {}
        public String createInvoice(Id accountId, Decimal amount) {
            if (accountId == failAccountId) {
                throw new BillingException(failMessage);
            }
            return successPrefix + String.valueOf(amount);
        }
    }

    // ---------- Helper ----------
    private static Id newOppId() {
        return fflib_IDGenerator.newId(Opportunity.SObjectType);
