    private class UnitOfWorkFactoryImpl implements fflib_IUnitOfWorkFactory {
        public fflib_ISObjectUnitOfWork newInstance() {
            fflib_SObjectUnitOfWork uow = new fflib_SObjectUnitOfWork();
            uow.registerSObjectType(Account.SObjectType);
            uow.registerSObjectType(Contact.SObjectType);
            uow.registerSObjectType(Opportunity.SObjectType);
            uow.registerSObjectType(OpportunityContactRole.SObjectType);
            uow.registerRelationship('Contact.AccountId', 'Account.Id');
            uow.registerRelationship('Opportunity.AccountId', 'Account.Id');
            uow.registerRelationship('OpportunityContactRole.OpportunityId', 'Opportunity.Id');
            uow.registerRelationship('OpportunityContactRole.ContactId', 'Contact.Id');
            return uow;
        }
    }

    private class ServiceFactoryImpl implements fflib_IServiceFactory {
        public Object newInstance(System.Type type) {
            if (type == IAccountsService.class) {
                return new AccountsServiceImpl();
            }
            throw new fflib_AppException('Unknown service type: ' + type);
        }
    }

    private class SelectorFactoryImpl implements fflib_ISelectorFactory {
        public List<SObject> selectById(Set<Id> recordIds) {
            return new AccountsSelector().selectById(recordIds);
        }

        public List<SObject> selectByRelationship(List<SObject> records, Schema.SObjectField relationshipField) {
            Map<Id, SObject> result = new Map<Id, SObject>();
            if (relationshipField == Contact.AccountId) {
                Set<Id> accountIds = new Set<Id>();
                for (Contact c : (List<Contact>) records) {
                    if (c.AccountId != null) accountIds.add(c.AccountId);
                }
                for (Account a : new AccountsSelector().selectById(accountIds)) {
                    result.put(a.Id, a);
                }
            } else if (relationshipField == Opportunity.AccountId) {
                Set<Id> accountIds = new Set<Id>();
                for (Opportunity o : (List<Opportunity>) records) {
                    if (o.AccountId != null) accountIds.add(o.AccountId);
                }
                for (Account a : new AccountsSelector().selectById(accountIds)) {
                    result.put(a.Id, a);
                }
            } else if (relationshipField == OpportunityContactRole.ContactId) {
                Set<Id> contactIds = new Set<Id>();
                for (OpportunityContactRole ocr : (List<OpportunityContactRole>) records) {
                    if (ocr.ContactId != null) contactIds.add(ocr.ContactId);
                }
                for (Contact c : new ContactsSelector().selectById(contactIds)) {
                    result.put(c.Id, c);
                }
            }
            return new List<SObject>(result.values());
        }
    }

    private class DomainFactoryImpl implements fflib_IDomainFactory {
        public fflib_IDomain newInstance(List<SObject> records) {
            return new Accounts((List<Account>) records);
        }

        public fflib_IDomain newInstance(List<Object> records, Object context) {
            return new Accounts((List<Account>) (List<SObject>) records);
        }

        public fflib_IDomain newInstance(List<SObject> records, Schema.SObjectType sobjectType) {
            return new Accounts((List<Account>) records);
        }
    }
