public class Opportunities extends fflib_SObjectDomain {

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> records) {
            return new Opportunities();
        }
    }

    public virtual void afterInsert(List<SObject> records) {
        Set<Id> qualifyingIds = new Set<Id>();
        for (SObject record : records) {
            Opportunity opp = (Opportunity) record;
            if (opp.StageName == 'Closed Won') {
                qualifyingIds.add(opp.Id);
            }
        }
        if (!qualifyingIds.isEmpty()) {
            IOpportunityFulfilmentService service =
                (IOpportunityFulfilmentService) Application.Service.newInstance(IOpportunityFulfilmentService.class);
            service.startFulfilment(qualifyingIds);
        }
    }

    public virtual void afterUpdate(List<SObject> records) {
        Set<Id> qualifyingIds = new Set<Id>();
        if (!records.isEmpty()) {
            Set<Id> ids = new Set<Id>();
            for (SObject record : records) {
                ids.add(record.Id);
            }
            Map<Id, Opportunity> oldOpps = new Map<Id, Opportunity>(
                [SELECT Id, StageName FROM Opportunity WHERE Id IN :ids]
            );
            for (SObject record : records) {
                Opportunity opp = (Opportunity) record;
                Opportunity oldOpp = oldOpps.get(opp.Id);
                if (oldOpp != null
                        && opp.StageName == 'Closed Won'
                        && oldOpp.StageName != 'Closed Won') {
                    qualifyingIds.add(opp.Id);
                }
            }
        }
        if (!qualifyingIds.isEmpty()) {
            IOpportunityFulfilmentService service =
                (IOpportunityFulfilmentService) Application.Service.newInstance(IOpportunityFulfilmentService.class);
            service.startFulfilment(qualifyingIds);
        }
    }
}
