public class AccountOnboardingService {

    /**
     * Creates one Account per map key and one Contact per last-name per account.
     * All SObjects are staged in a single fflib_SObjectUnitOfWork and committed
     * in one pass via commitWork(). No direct DML is issued by this class.
     *
     * @param contactLastNamesByAccountName  key = Account Name, value = list of Contact LastNames.
     * @return the newly created Accounts (Ids populated after commit).
     */
    public static List<Account> createAccountsWithContacts(Map<String, List<String>> contactLastNamesByAccountName) {
        if (contactLastNamesByAccountName == null || contactLastNamesByAccountName.isEmpty()) {
            return new List<Account>();
        }

        fflib_ConfigurableVariableAccessor cva = new fflib_ConfigurableVariableAccessor();
        fflib_SObjectUnitOfWork uow = new fflib_SObjectUnitOfWork(cva);
        fflib_StagingService staging = uow.getStagingService();
        List<Account> newAccounts = new List<Account>();

        for (String accountName : contactLastNamesByAccountName.keySet()) {
            Account acc = new Account(Name = accountName);
            staging.put(acc);
            newAccounts.add(acc);

            List<String> lastNames = contactLastNamesByAccountName.get(accountName);
            if (lastNames == null) {
                continue;
            }

            for (String lastName : lastNames) {
                Contact con = new Contact(
                    LastName = lastName,
                    AccountId = acc.Id
                );
                staging.put(con);
            }
        }

        // Single commit – fflib resolves parent-child Ids and issues the DML internally.
        uow.commitWork();

        return newAccounts;
    }
}
