public with sharing class LeadContactMatcher {

    /**
     * For each lead (same order and size), return the Id of the first Contact
     * whose Email matches the lead's Email (case-insensitive, trimmed), or null
     * if there is no match or the email is blank.
     *
     * No SOQL / DML is performed; all matching is in-memory.
     *
     * Complexity: O(n + m) where n = leads.size, m = contacts.size.
     */
    public static List<Id> matchByEmail(List<Lead> leads, List<Contact> contacts) {
        List<Id> results = new List<Id>();

        // Build a normalized-email → first-contact-Id map.
        // Because we only insert when the key is absent, the first contact
        // in list order wins when multiple contacts share an email.
        Map<String, Id> contactByEmail = new Map<String, Id>();
        for (Contact c : contacts) {
            String key = normalize(c.Email);
            if (key != null && !contactByEmail.containsKey(key)) {
                contactByEmail.put(key, c.Id);
            }
        }

        // One map lookup per lead.
        for (Lead l : leads) {
            String key = normalize(l.Email);
            results.add(key != null ? contactByEmail.get(key) : null);
        }

        return results;
    }

    /**
     * Returns a canonical (trimmed, lower-case) form of the email,
     * or null when the value is null, empty, or whitespace-only.
     */
    private static String normalize(String email) {
        if (email == null) {
            return null;
        }
        String trimmed = email.trim();
        if (trimmed.length() == 0) {
            return null;
        }
        return trimmed.toLowerCase();
    }
}
