public class CaseSurveyJob implements Queueable {

    private static final Integer BATCH_SIZE = 50;

    private final List<Id> caseIds;

    public CaseSurveyJob(List<Id> caseIds) {
        this.caseIds = caseIds;
    }

    public CaseSurveyJob(Id caseId) {
        this.caseIds = new List<Id>{ caseId };
    }

    public void execute(QueueableContext context) {
        Integer batchSize = caseIds.size() > BATCH_SIZE ? BATCH_SIZE : caseIds.size();

        List<Id> batch     = caseIds.sublist(0, batchSize);
        List<Id> remaining = caseIds.size() > BATCH_SIZE
                             ? caseIds.sublist(BATCH_SIZE)
                             : new List<Id>();

        processBatch(batch);

        // Chain another job if there are more cases to handle
        if (!remaining.isEmpty()) {
            System.enqueueJob(new CaseSurveyJob(remaining));
        }
    }

    private void processBatch(List<Id> ids) {
        Map<Id, Case> caseMap = new Map<Id, Case>([
            SELECT Id, CaseNumber, ContactId
            FROM Case
            WHERE Id IN :ids
        ]);

        List<Task> tasksToInsert = new List<Task>();

        for (Id id : ids) {
            Case c = caseMap.get(id);
            if (c == null || c.ContactId == null) {
                continue;
            }
            tasksToInsert.add(new Task(
                WhatId       = c.Id,
                WhoId        = c.ContactId,
                Subject      = 'CSAT survey: ' + c.CaseNumber,
                ActivityDate = Date.today().addDays(2),
                Status       = 'Not Started'
            ));
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }
    }
}
