            .catch((error) => {
                const message = error.body ? error.body.message : error.message;
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Could not save contacts',
                        message: message,
                        variant: 'error'
                    })
                );
            });
    }
