    _subscription;

    @wire(LightningMessageContext)
    wiredContext({ value }) {
        if (value) {
            this._messageContext = value;
            if (!this._subscription && this.isConnected) {
                this._subscription = subscribe(
                    value,
                    Account_Selected__c,
                    (message) => this.handleMessage(message),
                    { scope: APPLICATION_SCOPE }
                );
            }
        }
    }

    connectedCallback() {
        if (this._messageContext && !this._subscription) {
            this._subscription = subscribe(
                this._messageContext,
                Account_Selected__c,
                (message) => this.handleMessage(message),
                { scope: APPLICATION_SCOPE }
            );
        }
    }

    disconnectedCallback() {
        if (this._subscription) {
            unsubscribe(this._messageContext, this._subscription);
            this._subscription = null;
        }
