import { LightningElement, api } from 'lwc';

export default class StatusListbox extends LightningElement {
    @api label;
    @api options;

    _value = '';
    _activeIndex = 0;

    @api
    get value() {
        return this._value;
    }

    set value(val) {
        this._value = val;
        this._updateActiveIndex();
    }

    get activeDescendantId() {
        if (!this.options || this.options.length === 0) {
            return '';
        }
        return 'option-' + this._activeIndex;
    }

    get renderedOptions() {
        if (!this.options) {
            return [];
        }
        return this.options.map((opt, i) => ({
            id: 'option-' + i,
            value: opt.value,
            label: opt.label,
            isSelected: opt.value === this._value
        }));
    }

    connectedCallback() {
        this._updateActiveIndex();
    }

    _updateActiveIndex() {
        if (!this.options || this.options.length === 0) {
            this._activeIndex = 0;
            return;
        }
        const idx = this.options.findIndex((o) => o.value === this._value);
        this._activeIndex = idx >= 0 ? idx : 0;
    }

    handleKeydown(event) {
        const key = event.key;
        if (
            key !== 'ArrowDown' &&
            key !== 'ArrowUp' &&
            key !== 'Home' &&
            key !== 'End' &&
            key !== 'Enter' &&
            key !== ' '
        ) {
            return;
        }
        event.preventDefault();

        if (!this.options || this.options.length === 0) {
            return;
        }

        if (key === 'ArrowDown') {
            if (this._activeIndex < this.options.length - 1) {
                this._activeIndex++;
            }
        } else if (key === 'ArrowUp') {
            if (this._activeIndex > 0) {
                this._activeIndex--;
            }
        } else if (key === 'Home') {
            this._activeIndex = 0;
        } else if (key === 'End') {
            this._activeIndex = this.options.length - 1;
        } else {
            this._selectOption(this._activeIndex);
        }
    }

    handleClick(event) {
        const val = event.currentTarget.dataset.value;
        const idx = this.options.findIndex(
            (o) => String(o.value) === String(val)
        );
        if (idx !== -1) {
            this._activeIndex = idx;
            this._selectOption(idx);
        }
    }

    _selectOption(index) {
        const opt = this.options[index];
        if (!opt) {
            return;
        }
        if (opt.value === this._value) {
            return;
        }
        this._value = opt.value;
        this._activeIndex = index;
        this.dispatchEvent(
            new CustomEvent('change', { detail: { value: opt.value } })
