import { LightningElement, api } from 'lwc';

export default class StatusListbox extends LightningElement {
    @api label = '';

    _options = [];
    _value = '';
    _activeIndex = 0;

    @api
    get options() {
        return this._options;
    }
    set options(val) {
        this._options = Array.isArray(val) ? val : [];
        this._syncActiveIndex();
    }

    @api
    get value() {
        return this._value;
    }
    set value(val) {
        this._value = val;
        this._syncActiveIndex();
    }

    get items() {
        return this._options.map((opt, i) => ({
            id: `statusListbox-option-${i}`,
            value: opt.value,
            label: opt.label,
            selected: opt.value === this._value
        }));
    }

    get activeDescendantId() {
        if (this._options.length === 0) {
            return '';
        }
        return `statusListbox-option-${this._activeIndex}`;
    }

    _syncActiveIndex() {
        if (this._options.length === 0) {
            this._activeIndex = 0;
            return;
        }
        const idx = this._options.findIndex((opt) => opt.value === this._value);
        this._activeIndex = idx !== -1 ? idx : 0;
    }

    handleKeydown(event) {
        const key = event.key;
        const handledKeys = ['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '];

        if (handledKeys.indexOf(key) === -1) {
            return;
        }

        event.preventDefault();

        const len = this._options.length;
        if (len === 0) {
            return;
        }

        if (key === 'ArrowDown') {
            this._activeIndex = Math.min(this._activeIndex + 1, len - 1);
        } else if (key === 'ArrowUp') {
            this._activeIndex = Math.max(this._activeIndex - 1, 0);
        } else if (key === 'Home') {
            this._activeIndex = 0;
        } else if (key === 'End') {
            this._activeIndex = len - 1;
        } else if (key === 'Enter' || key === ' ') {
            this._selectOption(this._activeIndex);
        }
    }

    handleClick(event) {
        const el = event.currentTarget;
        const val = el.dataset.value;
        const idx = this._options.findIndex((opt) => opt.value === val);
        if (idx !== -1) {
            this._selectOption(idx);
        }
    }

    _selectOption(index) {
        const option = this._options[index];
        if (!option) {
            return;
        }
        this._activeIndex = index;
        if (option.value === this._value) {
            return;
        }
        this._value = option.value;
        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value: option.value }
            })
        );
    }
}
