/**
 * GiftImportService
 *
 * Routes one-off website gifts through the NPSP Data Importer (BDI) so that
 * NPSP's contact matching, household creation and donation-processing rules
 * apply, and each staged Data Import record remains in the org as an audit
 * trail of what was imported.
 */
public class GiftImportService {

    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        if (gifts == null || gifts.isEmpty()) {
            return new List<ImportResult>();
        }

        // --- 1. Stage one npsp__DataImport__c per gift -----------------------
        List<npsp__DataImport__c> stagedRecords = new List<npsp__DataImport__c>(gifts.size());

        for (WebGift gift : gifts) {
            npsp__DataImport__c di = new npsp__DataImport__c();
            di.npsp__Contact1_Firstname__c   = gift != null ? gift.firstName : null;
            di.npsp__Contact1_Lastname__c    = gift != null ? gift.lastName  : null;
            di.npsp__Contact1_Personal_Email__c = gift != null ? gift.email  : null;
            di.npsp__Donation_Amount__c      = gift != null ? gift.amount   : null;
            di.npsp__Donation_Date__c        = gift != null ? gift.giftDate : null;
            di.npsp__Donation_Donor__c       = 'Contact1';
            di.npsp__Status__c              = 'Pending';
            stagedRecords.add(di);
        }

        insert stagedRecords;

        // --- 2. Process synchronously via NPSP's Data Importer API ----------
        npsp__DataImporter.run(stagedRecords, null, true);

        // --- 3. Query back the results ---------------------------------------
        List<npsp__DataImport__c> processed = [
            SELECT Id,
                   npsp__Status__c,
                   npsp__Contact1Imported__c,
                   npsp__DonationImported__c,
                   npsp__FailureInformation__c
            FROM npsp__DataImport__c
            WHERE Id IN :stagedRecords
        ];

        Map<Id, npsp__DataImport__c> byId = new Map<Id, npsp__DataImport__c>();
        for (npsp__DataImport__c rec : processed) {
            byId.put(rec.Id, rec);
        }

        // --- 4. Build results in input order ---------------------------------
        List<ImportResult> results = new List<ImportResult>(gifts.size());
        for (Integer i = 0; i < stagedRecords.size(); i++) {
            npsp__DataImport__c rec = byId.get(stagedRecords.get(i).Id);
            ImportResult r = new ImportResult();

            if (rec != null && String.valueOf(rec.npsp__Status__c) == 'Imported') {
                r.success       = true;
                r.contactId     = rec.npsp__Contact1Imported__c;
                r.opportunityId = rec.npsp__DonationImported__c;
            } else {
                r.success = false;
                r.errorMessage = (rec != null && rec.npsp__FailureInformation__c != null)
                    ? rec.npsp__FailureInformation__c
                    : 'NPSP Data Import did not process the record.';
            }
            results.add(r);
        }

        return results;
    }

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;
        public Id opportunityId;
        public String errorMessage;
    }
}
