/**
 * Service for the event check-in app: registers a whole family (a list of new Contacts)
 * under a single NPSP Household Account in one call.
 *
 * In a production NPSP org the Account before-insert trigger sets the household Name
 * and generates greetings based on the primary contact. We provide a minimal Name
 * placeholder to satisfy the required-field constraint; NPSP overwrites it with the
 * proper household name on insert.
 */
public class HouseholdService {

    private static final String ACCOUNT_SOBJECT = 'Account';
    private static final String HOUSEHOLD_RT_DEVELOPER_NAME = 'HH_Account';

    /**
     * Creates one NPSP Household Account and assigns every member of {@code members} to it,
     * with the first contact in the list as the household's primary contact
     * (Account.npe01__One2OneContact__c).
     *
     * @param members New contacts (no Id, no AccountId). Must not be null or empty.
     * @return The Id of the newly created household Account.
     * @throws IllegalArgumentException if members is null or empty.
     */
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members must not be null or empty.');
        }

        // Resolve the Household Account record type by developer name (no hard-coded Id).
        RecordType householdRT = [
            SELECT Id
            FROM RecordType
            WHERE SObjectType = :ACCOUNT_SOBJECT
              AND DeveloperName = :HOUSEHOLD_RT_DEVELOPER_NAME
            LIMIT 1
        ];
        if (householdRT == null) {
            throw new IllegalArgumentException(
                'Household Account record type "' + HOUSEHOLD_RT_DEVELOPER_NAME + '" not found.');
        }

        // In a production NPSP org the before-insert trigger on Account sets the household
        // Name and generates greetings. We supply a minimal placeholder to satisfy the
        // required-field constraint; NPSP's trigger replaces it with the proper name.
        String placeholderName = buildPlaceholderName(members[0]);

        Account household = new Account(
            RecordTypeId = householdRT.Id,
            Name = placeholderName
        );
        Insert household;

        // Assign every member to this one household and insert them in a single bulk DML.
        for (Contact c : members) {
            c.Id = null;
            c.AccountId = household.Id;
        }
        Insert members;

        // First contact in the list is the household's primary contact.
        // Set the lookup after the contacts are inserted so the reference is valid.
        // NPSP's trigger on update will regenerate the household name and greetings.
        household.npe01__One2OneContact__c = members[0].Id;
        Update household;

        return household.Id;
    }

    /**
     * Builds a minimal placeholder name from the primary contact's fields.
     * In production NPSP's trigger overwrites this with the proper household name.
     */
    private static String buildPlaceholderName(Contact c) {
        String first = String.valueOf(c.FirstName);
        String last = String.valueOf(c.LastName);
        if (first != null && first != '' && last != null && last != '') {
            return first + ' ' + last;
        } else if (last != null && last != '') {
            return last;
        } else if (first != null && first != '') {
            return first;
        }
        return 'Household';
    }
}
