public with sharing class HouseholdService {
    private static final String HOUSEHOLD_RECORD_TYPE_DEVELOPER_NAME = 'HH_Account';

    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members must not be null or empty.');
        }

        for (Contact member : members) {
            if (member == null) {
                throw new IllegalArgumentException('members must not contain null contacts.');
            }
        }

        RecordType householdRecordType = [
            SELECT Id
            FROM RecordType
            WHERE SobjectType = 'Account'
              AND DeveloperName = :HOUSEHOLD_RECORD_TYPE_DEVELOPER_NAME
              AND IsActive = TRUE
            LIMIT 1
        ];

        if (householdRecordType == null) {
            throw new IllegalArgumentException('Household Account record type HH_Account was not found.');
        }

        // Build a placeholder name from the first contact so the required
        // Name field is satisfied; NPSP's trigger will overwrite it with the
        // proper household naming convention once contacts are associated.
        Contact primary = members.get(0);
        String firstName = (String.valueOf(primary.FirstName)).trim();
        String lastName = (String.valueOf(primary.LastName)).trim();
        String placeholderName = firstName + ' ' + lastName;
        if (placeholderName == '') {
            placeholderName = 'Household';
        }

        Account household = new Account(
            RecordTypeId = householdRecordType.Id,
            Name = placeholderName
        );
        insert household;

        // Associate every contact with the new household
        for (Contact member : members) {
            member.AccountId = household.Id;
        }
        insert members;

        // Mark the first contact as the primary (one-to-one) contact
        household.npe01__One2OneContact__c = members.get(0).Id;
        update household;

        return household.Id;
    }
}
