public class SoftCreditService {

    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        Set<Id> opportunityIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        for (SoftCreditRequest req : requests) {
            opportunityIds.add(req.opportunityId);
            contactIds.add(req.contactId);
        }

        // SOQL 1: Opportunities (amount + primary contact validation)
        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>(
            [SELECT Id, Amount, npsp__Primary_Contact__c FROM Opportunity WHERE Id IN :opportunityIds]
        );

        // SOQL 2: Existing Opportunity Contact Roles
        List<OpportunityContactRole> ocrList = [
            SELECT Id, OpportunityId, ContactId, Role
            FROM OpportunityContactRole
            WHERE OpportunityId IN :opportunityIds
            AND ContactId IN :contactIds
        ];
        Map<String, OpportunityContactRole> ocrMap = new Map<String, OpportunityContactRole>();
        for (OpportunityContactRole ocr : ocrList) {
            ocrMap.put(ocr.OpportunityId + '_' + ocr.ContactId, ocr);
        }

        // SOQL 3: Existing Partial Soft Credits
        List<npsp__Partial_Soft_Credit__c> pscList = [
            SELECT Id, npsp__Opportunity__c, npsp__Contact__c,
                   npsp__Amount__c, npsp__Role_Name__c, npsp__Contact_Role_ID__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :opportunityIds
            AND npsp__Contact__c IN :contactIds
        ];
        Map<String, npsp__Partial_Soft_Credit__c> pscMap = new Map<String, npsp__Partial_Soft_Credit__c>();
        for (npsp__Partial_Soft_Credit__c psc : pscList) {
            pscMap.put(psc.npsp__Opportunity__c + '_' + psc.npsp__Contact__c, psc);
        }

        // ── Validation (before any DML) ─────────────────────────────────────
        for (SoftCreditRequest req : requests) {
            Opportunity opp = oppMap.get(req.opportunityId);
            if (opp == null) {
                throw new SoftCreditException('Opportunity not found: ' + req.opportunityId);
            }
            if (req.contactId == opp.npsp__Primary_Contact__c) {
                throw new SoftCreditException(
                    'Contact ' + req.contactId + ' is the primary contact of opportunity ' + req.opportunityId);
            }
            if (req.amount == null || req.amount <= 0) {
                throw new SoftCreditException('Amount must be a positive number.');
            }
            if (opp.Amount != null && req.amount > opp.Amount) {
                throw new SoftCreditException(
                    'Amount ' + req.amount + ' exceeds opportunity amount ' + opp.Amount);
            }
        }

        // ── Plan OCR changes: delete stale-role OCRs, insert new ones ───────
        List<OpportunityContactRole> ocrsToDelete = new List<OpportunityContactRole>();
        List<OpportunityContactRole> ocrsToInsert = new List<OpportunityContactRole>();
        // key -> OCR that will exist after DML (existing or newly inserted)
        Map<String, OpportunityContactRole> resolvedOcrByKey = new Map<String, OpportunityContactRole>();

        for (SoftCreditRequest req : requests) {
            String key = req.opportunityId + '_' + req.contactId;
            OpportunityContactRole existing = ocrMap.get(key);

            if (existing == null) {
                OpportunityContactRole ocr = new OpportunityContactRole();
                ocr.OpportunityId = req.opportunityId;
                ocr.ContactId = req.contactId;
                ocr.Role = req.role;
                ocrsToInsert.add(ocr);
                resolvedOcrByKey.put(key, ocr);
            } else if (existing.Role != req.role) {
                // Remove the old role, will insert a replacement
                ocrsToDelete.add(existing);
                OpportunityContactRole ocr = new OpportunityContactRole();
                ocr.OpportunityId = req.opportunityId;
                ocr.ContactId = req.contactId;
                ocr.Role = req.role;
                ocrsToInsert.add(ocr);
                resolvedOcrByKey.put(key, ocr);
            } else {
                // Already has the correct role – reuse it
                resolvedOcrByKey.put(key, existing);
            }
        }

        // DML 1: Delete OCRs whose role must change
        if (!ocrsToDelete.isEmpty()) {
            delete ocrsToDelete;
        }

        // DML 2: Insert new / replacement OCRs
        if (!ocrsToInsert.isEmpty()) {
            insert ocrsToInsert;
        }

        // ── Plan Partial Soft Credit changes ─────────────────────────────────
        List<npsp__Partial_Soft_Credit__c> pscsToInsert = new List<npsp__Partial_Soft_Credit__c>();
        List<npsp__Partial_Soft_Credit__c> pscsToUpdate = new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest req : requests) {
            String key = req.opportunityId + '_' + req.contactId;
            OpportunityContactRole ocr = resolvedOcrByKey.get(key);
            npsp__Partial_Soft_Credit__c existingPsc = pscMap.get(key);

            if (existingPsc == null) {
                npsp__Partial_Soft_Credit__c psc = new npsp__Partial_Soft_Credit__c();
                psc.npsp__Opportunity__c = req.opportunityId;
                psc.npsp__Contact__c = req.contactId;
                psc.npsp__Amount__c = req.amount;
                psc.npsp__Role_Name__c = req.role;
                psc.npsp__Contact_Role_ID__c = String.valueOf(ocr.Id);
                pscsToInsert.add(psc);
            } else {
                existingPsc.npsp__Amount__c = req.amount;
                existingPsc.npsp__Role_Name__c = req.role;
                existingPsc.npsp__Contact_Role_ID__c = String.valueOf(ocr.Id);
                pscsToUpdate.add(existingPsc);
            }
        }

        // DML 3: Insert new Partial Soft Credits
        if (!pscsToInsert.isEmpty()) {
            insert pscsToInsert;
        }

        // DML 4: Update existing Partial Soft Credits
        if (!pscsToUpdate.isEmpty()) {
            update pscsToUpdate;
        }
    }
}
