public class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    public override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        List<Task> tasksToCreate = new List<Task>();

        if (triggerAction == npsp.TDTM_Runnable.Action.AfterInsert) {
            for (SObject so : newlist) {
                Opportunity opp = (Opportunity) so;
                if (String.equals(opp.StageName, 'Closed Won')
                    && opp.Amount != null
                    && opp.Amount >= 5000) {
                    tasksToCreate.add(new Task(
                        Subject      = 'Major gift thank-you call',
                        Priority     = 'High',
                        Status       = 'Not Started',
                        WhatId       = opp.Id,
                        WhoId        = opp.npsp__Primary_Contact__c,
                        OwnerId      = opp.OwnerId,
                        ActivityDate = opp.CloseDate != null ? opp.CloseDate.addDays(3) : null
                    ));
                }
            }
        }
        else if (triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate) {
            for (Integer i = 0; i < newlist.size(); i++) {
                Opportunity newOpp = (Opportunity) newlist[i];
                Opportunity oldOpp = (Opportunity) oldlist[i];

                Boolean newQualifies = String.equals(newOpp.StageName, 'Closed Won')
                    && newOpp.Amount != null
                    && newOpp.Amount >= 5000;

                Boolean oldQualifies = String.equals(oldOpp.StageName, 'Closed Won')
                    && oldOpp.Amount != null
                    && oldOpp.Amount >= 5000;

                if (newQualifies && !oldQualifies) {
                    tasksToCreate.add(new Task(
                        Subject      = 'Major gift thank-you call',
                        Priority     = 'High',
                        Status       = 'Not Started',
                        WhatId       = newOpp.Id,
                        WhoId        = newOpp.npsp__Primary_Contact__c,
                        OwnerId      = newOpp.OwnerId,
                        ActivityDate = newOpp.CloseDate != null ? newOpp.CloseDate.addDays(3) : null
                    ));
                }
            }
        }

        if (!tasksToCreate.isEmpty()) {
            insert tasksToCreate;
        }

        return new npsp.TDTM_Runnable.DmlWrapper();
    }
}
