        return new Task(
            Subject = 'Major gift thank-you call',
            Priority = 'High',
            Status = 'Not Started',
            WhatId = opp.Id,
            WhoId = opp.npsp__Primary_Contact__c,
            OwnerId = opp.OwnerId,
            ActivityDate = opp.CloseDate != null ? opp.CloseDate.addDays(3) : null
        );
