public with sharing class RecordAccessService {

    public static Set<Id> editableIds(Set<Id> recordIds) {
        if (recordIds == null || recordIds.isEmpty()) {
            return new Set<Id>();
        }

        Set<Id> validIds = new Set<Id>();
        for (Id id : recordIds) {
            if (id != null) {
                validIds.add(id);
            }
        }
        if (validIds.isEmpty()) {
            return new Set<Id>();
        }

        Map<String, String> prefixToType = buildPrefixToTypeMap();

        Map<String, Set<Id>> groupedByPrefix = new Map<String, Set<Id>>();
        for (Id id : validIds) {
            String prefix = String.valueOf(id).substring(0, 3);
            if (!groupedByPrefix.containsKey(prefix)) {
                groupedByPrefix.put(prefix, new Set<Id>());
            }
            groupedByPrefix.get(prefix).add(id);
        }

        Set<Id> result = new Set<Id>();
        for (String prefix : groupedByPrefix.keySet()) {
            String sobjectType = prefixToType.get(prefix);
            if (String.isBlank(sobjectType)) {
                continue;
            }

            Set<Id> typeIds = groupedByPrefix.get(prefix);

            List<SObject> accessibleRecords = Database.query(
                'SELECT Id FROM UserRecordAccess ' +
                'WHERE SobjectType = :sobjectType ' +
                'AND Id IN :typeIds ' +
                'AND HasEditAccess = TRUE'
            );

            for (SObject rec : accessibleRecords) {
                result.add((Id) rec.get('Id'));
            }
        }

        return result;
    }

    private static Map<String, String> buildPrefixToTypeMap() {
        Map<String, String> result = new Map<String, String>();
        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
        for (Schema.SObjectType st : globalDescribe.values()) {
            Schema.DescribeSObjectResult sdes = st.getDescribe();
            String prefix = sdes.getKeyPrefix();
            if (prefix != null && prefix.length() == 3) {
                result.put(prefix, sdes.getName());
            }
        }
        return result;
    }
}
