public with sharing class RecordAccessService {

    /**
     * Returns the subset of recordIds that the running user can edit,
     * as reported by the UserRecordAccess object (HasEditAccess = true).
     *
     * @param recordIds  Up to 2,000 record IDs (may span multiple objects).
     * @return A Set<Id> of IDs the user has edit access to. Never null.
     */
    public static Set<Id> editableIds(Set<Id> recordIds) {
        if (recordIds == null || recordIds.isEmpty()) {
            return new Set<Id>();
        }

        Set<Id> editable = new Set<Id>();
        List<Id> idList = new List<Id>(recordIds);
        Integer total = idList.size();
        Integer chunkSize = 1000; // SOQL IN-clause limit

        for (Integer i = 0; i < total; i += chunkSize) {
            Integer stop = Math.min(i + chunkSize, total);
            List<Id> chunk = new List<Id>();
            for (Integer j = i; j < stop; j++) {
                chunk.add(idList[j]);
            }

            List<UserRecordAccess> accesses = [
                SELECT RecordId
                FROM UserRecordAccess
                WHERE UserId = :UserInfo.getUserId()
                AND RecordId IN :chunk
                AND HasEditAccess = TRUE
            ];

            for (UserRecordAccess ura : accesses) {
                editable.add(ura.RecordId);
            }
        }

        return editable;
    }
}
```

**Fix applied:**

- `UserInfo.getId()` → `UserInfo.getUserId()` — the correct static method on `System.UserInfo` that returns the current user's ID as an `Id`.

