        List<Database.Error> errors = newOpp.getErrors();
        System.assertEquals(1, errors.size(), 'Expected exactly one error, got ' + errors.size());
        System.assertEquals(TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE, errors[0].message,
