```apex
public class TA_Case_RollupOpenCount
    implements TriggerAction.AfterInsert,
               TriggerAction.AfterUpdate,
               TriggerAction.AfterDelete,
               TriggerAction.AfterUndelete {

    public void afterInsert(List<SObject> triggerNew) {
        Set<Id> accountIds = new Set<Id>();
        for (SObject so : triggerNew) {
            Id accId = (Id) so.get('AccountId');
            if (accId != null) {
                accountIds.add(accId);
            }
        }
        recalculate(accountIds);
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Set<Id> accountIds = new Set<Id>();
        for (Integer i = 0; i < triggerNew.size(); i++) {
            Case cNew = (Case) triggerNew.get(i);
            Case cOld = (Case) triggerOld.get(i);
            if (cNew.IsClosed != cOld.IsClosed && cNew.AccountId != null) {
                accountIds.add(cNew.AccountId);
            }
            if (cNew.AccountId != cOld.AccountId) {
                if (cNew.AccountId != null) {
                    accountIds.add(cNew.AccountId);
                }
                if (cOld.AccountId != null) {
                    accountIds.add(cOld.AccountId);
                }
            }
        }
        recalculate(accountIds);
    }

    public void afterDelete(List<SObject> triggerOld) {
        Set<Id> accountIds = new Set<Id>();
        for (SObject so : triggerOld) {
            Id accId = (Id) so.get('AccountId');
            if (accId != null) {
                accountIds.add(accId);
            }
        }
        recalculate(accountIds);
    }

    public void afterUndelete(List<SObject> triggerNew) {
        Set<Id> accountIds = new Set<Id>();
        for (SObject so : triggerNew) {
            Id accId = (Id) so.get('AccountId');
            if (accId != null) {
                accountIds.add(accId);
            }
        }
        recalculate(accountIds);
    }

    private static void recalculate(Set<Id> accountIds) {
        if (accountIds.isEmpty()) {
            return;
        }
        Map<Id, Integer> openCounts = new Map<Id, Integer>();
        for (AggregateResult ar : [
            SELECT AccountId, COUNT(Id)
            FROM Case
            WHERE AccountId IN :accountIds AND IsClosed = false
            GROUP BY AccountId
        ]) {
            openCounts.put((Id) ar.get('AccountId'), (Integer) ar.get('expr0'));
        }
        List<Account> updates = new List<Account>();
        for (Id accId : accountIds) {
            updates.add(new Account(Id = accId, FB_Open_Case_Count__c = openCounts.getOrDefault(accId, 0)));
        }
        update updates;
    }
}
```

